/* Finished film-specific poster menus. Recipes and shopping lists are kept together.
   Add each approved edition here; existing films continue to work during the rollout. */
const MOVIE_MENU_EDITIONS = {
  "The Warriors (1979)": {
    poster: "assets/menu-posters/the-warriors-1979.jpg", colour: "#a52b20", servings: 4,
    tagline: "Last stop: Coney Island.",
    cue: "Bring out the chilli dogs when the journey heads back towards Coney Island.",
    menu: {
      s: [
        {n:"Boardwalk pretzel bites",note:"Warm, butter-brushed soft pretzels. Cheddar dip and yellow mustard.",how:"Mix 250g plain flour, 4g instant yeast, 1 tsp sugar, 1/2 tsp salt and 160ml warm water. Knead 8 minutes, cover and rise 1 hour. Roll into ropes and cut into 24 bites. Simmer 1 litre water with 30g bicarbonate of soda; boil bites in batches for 20 seconds, drain and bake on baking paper at 220°C for 12–15 minutes. Brush with 20g melted butter. For dip, melt 15g butter, stir in 15g flour, whisk in 150ml milk and simmer 2 minutes. Remove from heat and stir in 100g grated cheddar. Serve with mustard.",shop:["250g + 15g plain flour@Pantry","4g instant yeast@Pantry","1 tsp sugar@Pantry","1/2 tsp salt@Pantry","30g bicarbonate of soda@Pantry","35g butter@Dairy","150ml milk@Dairy","100g cheddar@Dairy","yellow mustard@Pantry"]},
        {n:"Street-cart corn",note:"Charred corn ribs, chilli butter, lime and smoked salt.",how:"Quarter 4 corn cobs lengthways on a secure board with a sturdy sharp knife; use whole cobs if easier. Brush with 30g melted butter mixed with 1/2 tsp chilli flakes and a pinch of smoked salt. Roast at 220°C for 20–25 minutes, turning once, until tender and charred at the edges. Finish with the juice of 1 lime.",shop:["4 corn cobs@Produce","1 lime@Produce","30g butter@Dairy","1/2 tsp chilli flakes@Pantry","smoked salt@Pantry"]}
      ],
      m: [{n:"Coney Island chilli dogs",note:"Griddled beef franks, rich beef chilli, diced onion and mustard. Shoestring fries on the side.",how:"Dice 1 onion; reserve a quarter for topping. Fry the rest in 1 tbsp oil with 2 minced garlic cloves, add 400g beef mince and brown well. Stir in 1 tbsp tomato paste, 1 tsp each ground cumin and smoked paprika, 400g tinned tomatoes and 100ml water. Simmer 25 minutes; season with salt. Bake 600g shoestring fries as directed on the packet. Griddle 8 beef franks until piping hot and warm 8 buns. Fill buns with franks and chilli; finish with reserved onion and mustard. Serve fries alongside.",shop:["400g beef mince@Meat","8 beef franks@Meat","8 hot dog buns@Bakery","600g shoestring fries@Frozen","1 onion@Produce","2 garlic cloves@Produce","1 tbsp oil@Pantry","1 tbsp tomato paste@Pantry","1 tsp ground cumin@Pantry","1 tsp smoked paprika@Pantry","400g tinned tomatoes@Pantry","salt@Pantry","yellow mustard@Pantry"]}],
      w: [{n:"Chocolate-dipped ice-cream sandwiches",note:"Vanilla ice cream, chewy chocolate cookies and dark chocolate.",how:"Soften 500ml vanilla ice cream just enough to scoop. Sandwich between 8 large chewy chocolate cookies to make 4 sandwiches. Freeze on a lined tray for 1 hour. Melt 150g dark chocolate gently, cool until just warm, dip half of each sandwich and return to the freezer for 15 minutes. Make ahead so they're ready when the film finishes.",shop:["500ml vanilla ice cream@Frozen","8 large chewy chocolate cookies@Bakery","150g dark chocolate@Pantry"]}],
      d: [{n:"Cherry cola",note:"Ice-cold cola, cherry syrup and a squeeze of lime.",how:"Fill 4 glasses with ice. Add 15ml cherry syrup to each, top each with 250ml cola and squeeze in a lime wedge. Stir once. Taste before adding more syrup.",shop:["1 litre cola@Drinks","60ml cherry syrup@Drinks","1 lime@Produce","ice@Frozen"]}]
    }
  },
  "Ghostbusters (1984)": {
    poster:"assets/menu-posters/ghostbusters-1984.jpg",colour:"#bc2c28",servings:4,
    tagline:"Firehouse night shift.",cue:"Serve the takeaway boxes when the team settles in at the firehouse.",
    menu:{
      s:[
        {n:"Slimer's green dip",note:"Hot spinach, artichoke and melted cheese. Scoop with crisp corn chips.",how:"Thaw 150g frozen spinach and squeeze very dry. Chop 150g drained marinated artichokes. Mix with 150g cream cheese, 100g sour cream, 75g grated mozzarella and 1 crushed garlic clove. Spoon into a small baking dish, top with 25g mozzarella and bake at 190°C for 20–25 minutes until bubbling. Serve with 200g corn chips.",shop:["150g frozen spinach@Frozen","150g drained marinated artichokes@Pantry","150g cream cheese@Dairy","100g sour cream@Dairy","100g mozzarella@Dairy","1 garlic clove@Produce","200g corn chips@Pantry"]},
        {n:"Firehouse wings",note:"Crispy chicken wings, Buffalo sauce and cooling ranch.",how:"Pat 800g separated chicken wings dry. Toss with 1 tsp baking powder (not bicarbonate), 1/2 tsp salt and 1 tsp smoked paprika. Spread on a rack over a lined tray and roast at 220°C for 40–45 minutes, turning halfway, until browned and at least 74°C in the thickest part. Mix 40ml hot sauce with 30g melted butter and toss with wings. Serve with 100ml ranch; leave some wings unsauced for a milder option.",shop:["800g chicken wings@Meat","1 tsp baking powder@Pantry","1/2 tsp salt@Pantry","1 tsp smoked paprika@Pantry","40ml hot sauce@Pantry","30g butter@Dairy","100ml ranch dressing@Pantry"]}
      ],
      m:[{n:"New York sesame chicken",note:"Sticky sesame chicken, wok-fried egg rice and blistered broccoli. Serve in takeaway boxes.",how:"Cut 600g boneless chicken thighs into bite-size pieces, toss with 3 tbsp cornflour and shallow-fry in batches until crisp and at least 74°C inside. Drain. Mix 2 tbsp each soy sauce and honey, 1 tbsp rice vinegar, 1 tsp sesame oil, 2 crushed garlic cloves and 60ml water. Simmer, thicken with 1 tsp cornflour mixed with 1 tbsp water, then toss through chicken and 1 tbsp sesame seeds. Fry 2 beaten eggs in 1 tbsp oil; add 500g chilled cooked rice, 2 sliced spring onions and 1 tbsp soy sauce. Stir-fry until piping hot. Char 1 head broccoli in a hot pan with 1 tbsp oil and a splash of water. Divide everything into 4 takeaway boxes.",shop:["600g boneless chicken thighs@Meat","3 tbsp + 1 tsp cornflour@Pantry","neutral oil for frying@Pantry","3 tbsp soy sauce@Pantry","2 tbsp honey@Pantry","1 tbsp rice vinegar@Pantry","1 tsp sesame oil@Pantry","2 garlic cloves@Produce","1 tbsp sesame seeds@Pantry","2 eggs@Dairy","500g chilled cooked rice@Pantry","2 spring onions@Produce","1 head broccoli@Produce"]}],
      w:[{n:"Stay Puft brownie skillet",note:"Warm chocolate brownie, toasted marshmallow and vanilla ice cream.",how:"Melt 100g butter with 100g dark chocolate and cool slightly. Whisk in 120g caster sugar and 2 eggs, then fold in 60g plain flour, 15g cocoa and a pinch of salt. Pour into a buttered 20cm ovenproof skillet or baking dish. Bake at 180°C for 20–25 minutes until the edges are set and the centre is fudgy. Top with 100g marshmallows and grill briefly until golden, watching closely. Serve with 400ml vanilla ice cream.",shop:["100g butter@Dairy","100g dark chocolate@Pantry","120g caster sugar@Pantry","2 eggs@Dairy","60g plain flour@Pantry","15g cocoa powder@Pantry","salt@Pantry","100g marshmallows@Pantry","400ml vanilla ice cream@Frozen"]}],
      d:[{n:"Green citrus slush",note:"Orange, lime and lemonade, blended with ice. Suspiciously green. Completely drinkable.",how:"Blend 300ml orange juice, juice of 2 limes, 300ml lemonade and 400g ice until slushy. Add a tiny drop of green food colouring if wanted. Divide into 4 glasses and serve immediately.",shop:["300ml orange juice@Drinks","2 limes@Produce","300ml lemonade@Drinks","400g ice@Frozen","green food colouring (optional)@Pantry"]}]
    }
  },
  "The Godfather (1972)": {
    poster:"assets/menu-posters/the-godfather-1972.jpg",colour:"#743525",servings:4,
    tagline:"A Sunday at the Corleone table.",cue:"Set out the antipasto during Connie's wedding, then bring the Sunday sauce to the table.",
    menu:{
      s:[
        {n:"Wedding antipasto",note:"Salami, aged provolone, olives and roast peppers.",how:"Arrange 100g sliced salami, 100g aged provolone, 100g olives and 150g drained roast capsicum on a platter. Drizzle the capsicum with olive oil and add a little cracked pepper. Serve at room temperature while the main simmers.",shop:["100g salami@Deli","100g aged provolone@Deli","100g olives@Deli","150g roast capsicum@Deli","olive oil@Pantry","black pepper@Pantry"]},
        {n:"Golden arancini",note:"Crisp risotto balls with a melting mozzarella centre.",how:"Use 400g cold, thick cooked risotto. Divide into 8 portions and wrap each around a cube cut from 80g mozzarella. Roll into balls, dust with 40g flour, dip in 1 beaten egg and coat in 80g breadcrumbs. Chill 20 minutes. Fry in 170°C neutral oil in batches until golden and hot throughout, about 4–5 minutes; drain. Make the risotto the day before, cool promptly and refrigerate, or use 8 ready-made mozzarella arancini following the packet instructions.",shop:["400g cold cooked risotto or 8 ready-made arancini@Deli","80g mozzarella@Dairy","40g plain flour@Pantry","1 egg@Dairy","80g breadcrumbs@Pantry","neutral oil for frying@Pantry"]}
      ],
      m:[{n:"Clemenza's Sunday sauce",note:"Pork and beef meatballs, fennel sausage and slow-simmered tomato sauce. Rigatoni and pecorino at the table.",how:"Mix 400g pork and beef mince with 1 egg, 40g breadcrumbs, 30g grated pecorino and a pinch of salt; form 12 meatballs. Brown in olive oil with 3 fennel sausages cut into chunks; set aside. Soften 1 diced onion, add 3 sliced garlic cloves and 2 tbsp tomato paste. Stir in 800g tinned tomatoes and 200ml water. Return meat, cover partly and simmer gently 60–90 minutes, stirring and adding water if needed. Check meatballs are cooked through. Boil 400g rigatoni, toss with sauce and serve with the meat and another 30g pecorino.",shop:["400g pork and beef mince@Meat","3 fennel sausages@Meat","1 egg@Dairy","40g breadcrumbs@Pantry","60g pecorino@Dairy","olive oil@Pantry","salt@Pantry","1 onion@Produce","3 garlic cloves@Produce","2 tbsp tomato paste@Pantry","800g tinned tomatoes@Pantry","400g rigatoni@Pantry"]}],
      w:[{n:"Ricotta & pistachio cannoli",note:"Crisp shells, orange-scented ricotta, dark chocolate and crushed pistachio.",how:"Drain 250g ricotta in a lined sieve in the fridge for at least 2 hours. Beat with 40g icing sugar and zest of 1 orange; fold in 30g finely chopped dark chocolate. Pipe into 8 small bought cannoli shells just before serving. Dip ends into 30g crushed pistachios and dust lightly with icing sugar.",shop:["250g ricotta@Dairy","40g icing sugar@Pantry","1 orange@Produce","30g dark chocolate@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry"]}],
      d:[{n:"Blood orange Italian soda",note:"Blood orange syrup, sparkling water and a fresh orange twist.",how:"Fill 4 glasses with ice. Add 25ml blood orange syrup to each and top each with 200ml sparkling water. Stir gently and finish with a thin twist from 1 orange. Adjust syrup to taste.",shop:["100ml blood orange syrup@Drinks","800ml sparkling water@Drinks","1 orange@Produce","ice@Frozen"]}]
    }
  }
};
